  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `priority` int NOT NULL DEFAULT '0',
  `stackable` tinyint(1) DEFAULT '0',
  `customer_scope` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ALL',
  `eligible_user_account_id` bigint DEFAULT NULL,
