  KEY `idx_promotions_eligible_user_account_id` (`eligible_user_account_id`),
  CONSTRAINT `fk_promotions_eligible_user_account` FOREIGN KEY (`eligible_user_account_id`) REFERENCES `user_accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_promotions_discount_value_non_negative` CHECK ((`discount_value` >= 0)),
