INSERT INTO `promotions` VALUES (1,'Khuyến Mãi Hè 2026 - Giảm Giá Toàn Bộ Sản Phẩm','Giảm giá mùa hè dành cho tất cả khách hàng khi mua sắm trên website. Áp dụng cho toàn bộ sản phẩm thời trang và phụ kiện.','PERCENTAGE',15.00,20000.00,50000.00,'VND','ACTIVE',10,0,'ALL',NULL,NULL,'2025-12-31 17:00:00.000000','2026-12-31 16:59:00.000000','2026-06-08 09:07:09.744997','2026-06-09 15:48:04.773618'),(2,'Flash Sale Cuối Tuần','Ưu đãi đặc biệt trong 48 giờ cuối tuần với số lượng giới hạn.','PERCENTAGE',25.00,27000.00,0.00,'VND','ACTIVE',100,1,'ALL',NULL,NULL,'2026-06-06 17:00:00.000000','2026-06-14 16:59:00.000000','2026-06-08 11:59:39.245611','2026-06-09 15:35:07.147457');
